{"command": "cd /workspace/tools && python3 -c "
import importlib.util, json
spec = importlib.util.spec_from_file_location('cde','/workspace/tools/cde_calc.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
for tid in ['T-01','T-02','T-03','T-04','T-05','T-06','T-07','T-08']:
    for occ in ['tot']:
        out, rows = m.run(tid, occ)
        print(tid, 'occ=',out['occupancy_basis'], 'wc=',out['weapon_class'], out['fuze'], 'CER',out['cer_m'], 'LEVEL',out['cde_level'], 'est',out['nc_casualty_estimate'], 'ncv',out['ncv'], '|', out['approval_authority'], '| NSL:', out['nsl_within_cer'])
    print()
""}

{"command": "cd /workspace/out && ls -la && echo "--- markdown table sanity (pipe counts per row) ---" && python3 - <<'EOF'
for f in ['strike_package.md','loac_annex.md']:
    print("==",f)
    lines=open(f).read().splitlines()
    bad=[l for l in lines if l.startswith('|') and l.count('|')<3]
    print("  lines:",len(lines),"| malformed table rows:",len(bad))
    for l in lines:
        if l.startswith('|') and l.count('|')<3: print("   !",l)
print()
print(open('cde_summary.csv').read())
EOF"}

